import itertools
import networkx as nx

def count_weak_quartets(G):
    n = G.number_of_nodes()
    weak_quartets = 0
    for quartet in itertools.combinations(range(n), 4):
        subgraph = G.subgraph(quartet)
        if subgraph.number_of_edges() == 1:
            weak_quartets += 1
    return weak_quartets

def solve_small(n):
    max_w = 0
    best_edges = 0
    # We need to iterate over all possible graphs? That's 2^(n*(n-1)/2).
    # Too many. Let's try some specific types of graphs.

    # 1. Star graphs
    for m in range(1, n):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for i in range(1, m + 1):
            G.add_edge(0, i)
        w = count_weak_quartets(G)
        if w > max_w:
            max_w = w
            best_edges = m

    # 2. Complete graphs plus isolated vertices
    for k in range(1, n + 1):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for i in range(k):
            for j in range(i + 1, k):
                G.add_edge(i, j)
        w = count_weak_quartets(G)
        if w > max_w:
            max_w = w
            best_edges = k*(k-1)//2

    # 3. Disjoint edges
    for m in range(1, n // 2 + 1):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for i in range(m):
            G.add_edge(2*i, 2*i+1)
        w = count_weak_quartets(G)
        if w > max_w:
            max_w = w
            best_edges = m

    # 4. Complete bipartite graphs
    for k in range(1, n):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for i in range(k):
            for j in range(k, n):
                G.add_edge(i, j)
        w = count_weak_quartets(G)
        if w > max_w:
            max_w = w
            best_edges = k*(n-k)

    return max_w

for n in range(5, 11):
    print(f"n={n}, max_w={solve_small(n)}")

import itertools
import networkx as nx

def count_weak_quartets(G):
    n = G.number_of_nodes()
    weak_quartets = 0
    for quartet in itertools.combinations(range(n), 4):
        subgraph = G.subgraph(quartet)
        if subgraph.number_of_edges() == 1:
            weak_quartets += 1
    return weak_quartets

def brute_force_max(n):
    max_w = 0
    edges_list = list(itertools.combinations(range(n), 2))
    num_edges = len(edges_list)
    for i in range(2**num_edges):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for j in range(num_edges):
            if (i >> j) & 1:
                G.add_edge(*edges_list[j])
        w = count_weak_quartets(G)
        if w > max_w:
            max_w = w
    return max_w

print(f"n=5, brute={brute_force_max(5)}")
print(f"n=6, brute={brute_force_max(6)}")
